function AdminLogin({ onLogin }) {
  const [email, setEmail] = useState('admin@lumiere.test');
  const [password, setPassword] = useState('ChangeMe123!');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const submit = async (event) => {
    event.preventDefault(); setLoading(true); setError('');
    try {
      const response = await fetch('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Unable to sign in');
      onLogin(data.token);
    } catch (err) { setError(err.message); } finally { setLoading(false); }
  };
  return <div className="login-shell"><div className="login-card"><div className="admin-brand login-brand"><span className="brand-mark">l</span><div><strong>lumière</strong><small>commerce studio</small></div></div><p className="eyebrow">Secure admin access</p><h1>Welcome back.</h1><p className="login-copy">Sign in to manage your catalog, orders, customers, and store settings.</p><form onSubmit={submit}><label>Email<input type="email" value={email} onChange={e => setEmail(e.target.value)} autoComplete="username" required /></label><label>Password<input type="password" value={password} onChange={e => setPassword(e.target.value)} autoComplete="current-password" required /></label>{error && <p className="login-error">{error}</p>}<button className="admin-primary login-submit" disabled={loading}>{loading ? 'Signing in…' : 'Sign in'} <ArrowRight size={15}/></button></form></div></div>;
}

