  return <><div className="dash-heading"><div><p className="eyebrow">Live store overview</p><h1>Good morning, Amelia <span>✦</span></h1><p className="muted">{loading ? 'Loading your store data…' : 'Current data from your database and Firebase sync.'}</p></div><button className="admin-primary" onClick={load}><ArrowRight size={16}/> Refresh data</button></div><div className="metric-grid"><Metric label="Total revenue" value={formatINR(metrics.revenueCents / 100)} delta="Live" note="from paid orders"/><Metric label="Orders" value={metrics.orders} delta="Live" note="orders in database"/><Metric label="Customers" value={metrics.customers} delta="Live" note="registered customers"/><Metric label="Average order" value={formatINR(average / 100)} delta="Live" note="current average"/></div><div className="dashboard-grid"><section className="panel sales-panel"><div className="panel-head"><div><h2>Sales overview</h2><p className="muted">Live order activity</p></div><span className="live-label"><i></i> Live</span></div>{orders.length ? <div className="live-sales"><strong>{orders.length}</strong><span>orders recorded</span><div className="live-bars">{orders.slice(0, 10).map((order, index) => <div key={order.id} style={{ height: `${35 + ((index * 17) % 60)}%` }}></div>)}</div></div> : <div className="empty-table"><BarChart3 size={24}/><p>Sales chart will populate when customers place orders.</p></div>}</section><section className="panel orders-panel"><div className="panel-head"><div><h2>Recent orders</h2><p className="muted">Live order queue</p></div><button className="view-all" onClick={() => document.querySelector('.admin-nav:nth-of-type(3)')?.click()}>View all <ArrowRight size={14}/></button></div><div className="orders-list">{recentOrders.length ? recentOrders.map(order => <Order key={order.id} name={order.name || 'Guest customer'} id={`#${String(order.id).padStart(4,'0')}`} item={order.payment_method === 'phonepe' ? 'PhonePe / UPI' : 'Cash on Delivery'} amount={formatINR(order.total_cents / 100)} status={order.payment_status || order.status} initials={(order.name || 'GC').slice(0,2).toUpperCase()}/>) : <div className="empty-table"><Package size={20}/><p>No orders yet.</p></div>}</div></section></div><div className="bottom-grid"><section className="panel"><div className="panel-head"><div><h2>Catalog</h2><p className="muted">Live products from your database</p></div><button className="view-all" onClick={load}>Refresh <ArrowRight size={14}/></button></div><div className="top-products">{products.slice(0, 4).map((product, index) => <TopProduct key={product.id} n={String(index + 1).padStart(2,'0')} name={product.name} sold={`${product.inventory} in stock`} amount={formatINR(product.price_cents / 100)} img={product.image}/>)}</div></section><section className="panel stock-panel"><div className="panel-head"><div><h2>Inventory alert</h2><p className="muted">Live stock levels</p></div></div>{lowStock.length ? lowStock.map(product => <div className="stock-item" key={product.id}><div className="tiny-thumb">{product.image && <img src={product.image}/>}</div><div><strong>{product.name}</strong><span>Only {product.inventory} units left</span></div><span className="low-stock">Low stock</span></div>) : <div className="empty-table"><Check size={20}/><p>No low-stock products.</p></div>}</section></div></>;
