const MAX_PRODUCT_IMAGE_BYTES = 650000;
async function compressProductImage(file) {
  if (!file?.type?.startsWith('image/')) throw new Error('Please select an image file.');
  const source = await createImageBitmap(file);
  let width = source.width; let height = source.height; const maxSide = 1100;
  if (Math.max(width, height) > maxSide) { const scale = maxSide / Math.max(width, height); width = Math.round(width * scale); height = Math.round(height * scale); }
  const canvas = document.createElement('canvas'); const context = canvas.getContext('2d'); canvas.width = width; canvas.height = height; context.drawImage(source, 0, 0, width, height); source.close?.();
  let quality = 0.84; let output = canvas.toDataURL('image/webp', quality);
  while (output.length > MAX_PRODUCT_IMAGE_BYTES && quality > 0.45) { quality -= 0.08; output = canvas.toDataURL('image/webp', quality); }
  if (output.length > MAX_PRODUCT_IMAGE_BYTES) throw new Error('That image is still too large. Choose a smaller image or crop it before uploading.');
  return output;
}
function ProductImageField({ value, onChange, onError }) {
  const [busy, setBusy] = useState(false);
  const upload = async event => { const file = event.target.files?.[0]; if (!file) return; setBusy(true); try { onChange(await compressProductImage(file)); } catch (error) { onError(error.message); } finally { setBusy(false); event.target.value = ''; } };
  return <div className="product-image-field"><label>Upload product image<input type="file" accept="image/*" onChange={upload} disabled={busy}/><small>{busy ? 'Optimizing image…' : 'Images are compressed and saved securely in the database. Maximum 650 KB.'}</small></label><span>or use an image URL</span><input type="url" value={value} onChange={event => onChange(event.target.value)} placeholder="https://…"/>{value && <img src={value} onError={imageWithFallback} alt="Product preview"/>}</div>;
}

function ProductCategorySelect({ value, onChange }) {
  const [categories, setCategories] = useState(defaultCategoryOptions);
  useEffect(() => {
    let active = true;
    fetch('/api/categories').then(response => response.ok ? response.json() : Promise.reject())
      .then(data => { if (active && data.categories?.length) setCategories(data.categories); }).catch(() => {});
    return () => { active = false; };
  }, []);
  return <select value={value} onChange={onChange}>{categories.map(category => <option key={category.id} value={category.name}>{category.name}</option>)}</select>;
}

function ProductModal({ open, onClose }) {
  const [form, setForm] = useState({ name: '', type: 'Complexion', price: '', compareAt: '', inventory: '', shade: '', image: '', description: '' });
  const [status, setStatus] = useState('');
  if (!open) return null;
  const update = (key) => (event) => setForm(current => ({ ...current, [key]: event.target.value }));
  const submit = async (event) => {
    event.preventDefault(); setStatus('Saving…');
    try {
      const response = await fetch('/api/admin/products', { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${localStorage.getItem('lumiere_admin_token')}` }, body: JSON.stringify({ name: form.name, type: form.type, priceCents: Math.round(Number(form.price) * 100), compareAtCents: form.compareAt ? Math.round(Number(form.compareAt) * 100) : null, inventory: Number(form.inventory || 0), shade: form.shade, image: form.image, description: form.description }) });
      const data = await response.json();
      if (!response.ok) throw new Error(data.error || 'Could not save product');
      setStatus('Product saved');
      setTimeout(onClose, 650);
    } catch (error) { setStatus(error.message); }
  };
  return <div className="modal-backdrop" onClick={onClose}><div className="product-modal" onClick={event => event.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">Catalog</p><h2>Add product</h2></div><button className="icon-button" onClick={onClose}><X size={19}/></button></div><form onSubmit={submit}><label>Product name<input value={form.name} onChange={update('name')} placeholder="e.g. Soft Glow Mist" required /></label><div className="form-row"><label>Category<ProductCategorySelect value={form.type} onChange={update('type')} /></label><label>Sale price (INR)<input type="number" min="0" step="1" value={form.price} onChange={update('price')} placeholder="2499" required /></label></div><div className="form-row"><label>MRP (INR)<input type="number" min="0" step="1" value={form.compareAt} onChange={update('compareAt')} placeholder="2999" /></label><label>Inventory<input type="number" min="0" step="1" value={form.inventory} onChange={update('inventory')} placeholder="0" required /></label></div><label>Shade / size<input value={form.shade} onChange={update('shade')} placeholder="4 shades" /></label><label>Description<textarea value={form.description} onChange={update('description')} placeholder="Describe the product, finish, and key benefits." rows="4" /></label><ProductImageField value={form.image} onChange={image => setForm(current => ({ ...current, image }))} onError={setStatus}/>{status && <p className={status === 'Product saved' ? 'form-success' : 'form-error'}>{status}</p>}<div className="modal-actions"><button type="button" className="cancel-btn" onClick={onClose}>Cancel</button><button className="admin-primary" disabled={status === 'Saving…'}>{status === 'Saving…' ? 'Saving…' : 'Save product'} <ArrowRight size={15}/></button></div></form></div></div>;
}

function Metric({label,value,delta,note}) { return <div className="metric-card"><div className="metric-icon"><BarChart3 size={16}/></div><span>{label}</span><strong>{value}</strong><div className="delta"><b>↑ {delta}</b> {note}</div></div> }
